use std::fs
use std::env

fn emit(text: string, number: bool, counter: int) -> int {
    let mut n = counter
    if number {
        for line in text.lines() {
            n += 1
            let s = "${n}"
            let pad = 6 - s.len()
            let mut p = ""
            let mut i = 0
            while i < pad {
                p = p + " "
                i += 1
            }
            println("${p}${s}\t${line}")
        }
    } else {
        print(text)
    }
    n
}

fn main() {
    let mut number = false
    let mut files: Vec<string> = []
    let mut first = true
    for a in env::args() {
        if first {
            first = false
        } else if a == "-n" {
            number = true
        } else {
            files.push(a)
        }
    }
    let mut counter = 0
    let mut status = 0
    if files.len() == 0 {
        let text = fs::read_to_string("/dev/stdin").unwrap_or("")
        counter = emit(text, number, counter)
    } else {
        for f in files {
            match fs::read_to_string(f) {
                Ok(text) => {
                    counter = emit(text, number, counter)
                }
                Err(_) => {
                    println("cat: ${f}: No such file")
                    status = 1
                }
            }
        }
    }
    if status != 0 {
        std::process::exit(status)
    }
}

